class Solution {
public:
    int beautifulPartitions(string s, int k, int minLength){
        const long long MOD=1e9+7;
        auto pr=[](char c){return c=='2'||c=='3'||c=='5'||c=='7';};
        int n=s.size();
        if(pr(s[0])==false||pr(s[n-1])) return 0;
        vector<int> pts; pts.push_back(0);
        for(int i=1;i<n;i++) if(!pr(s[i-1])&&pr(s[i])) pts.push_back(i);
        pts.push_back(n);
        int m=pts.size();
        vector<long long> dp(m,0); dp[0]=1;
        for(int j=0;j<k;j++){
            vector<long long> pre(m+1,0),ndp(m,0);
            for(int t=0;t<m;t++) pre[t+1]=(pre[t]+dp[t])%MOD;
            for(int t=1;t<m;t++){
                int lim=pts[t]-minLength;
                int idx=upper_bound(pts.begin(),pts.end(),lim)-pts.begin()-1;
                if(idx>=0) ndp[t]=pre[idx+1]%MOD;
            }
            dp=ndp;
        }
        return dp[m-1];
    }
};

