class Solution {
    public int beautifulPartitions(String s, int k, int minLength){
        final long MOD=1_000_000_007L;
        int n=s.length();
        if("2357".indexOf(s.charAt(0))<0||"2357".indexOf(s.charAt(n-1))>=0) return 0;
        List<Integer> pl=new ArrayList<>(); pl.add(0);
        for(int i=1;i<n;i++) if("2357".indexOf(s.charAt(i-1))<0&&"2357".indexOf(s.charAt(i))>=0) pl.add(i);
        pl.add(n);
        int[] pts=pl.stream().mapToInt(Integer::intValue).toArray();
        int m=pts.length;
        long[] dp=new long[m]; dp[0]=1;
        for(int j=0;j<k;j++){
            long[] pre=new long[m+1],ndp=new long[m];
            for(int t=0;t<m;t++) pre[t+1]=(pre[t]+dp[t])%MOD;
            for(int t=1;t<m;t++){
                int lim=pts[t]-minLength;
                int lo=0,hi=m-1,idx=-1;
                while(lo<=hi){int mid=(lo+hi)/2;if(pts[mid]<=lim){idx=mid;lo=mid+1;}else hi=mid-1;}
                if(idx>=0) ndp[t]=pre[idx+1]%MOD;
            }
            dp=ndp;
        }
        return (int)dp[m-1];
    }
}

