var beautifulPartitions = function(s, k, minLength) {
    const MOD=1e9+7, pr=c=>'2357'.includes(c), n=s.length;
    if(!pr(s[0])||pr(s[n-1])) return 0;
    const pts=[0];
    for(let i=1;i<n;i++) if(!pr(s[i-1])&&pr(s[i])) pts.push(i);
    pts.push(n);
    const m=pts.length;
    let dp=Array(m).fill(0); dp[0]=1;
    for(let j=0;j<k;j++){
        const pre=[0], ndp=Array(m).fill(0);
        for(let t=0;t<m;t++) pre.push((pre[t]+dp[t])%MOD);
        for(let t=1;t<m;t++){
            const lim=pts[t]-minLength;
            let lo=0,hi=m-1,idx=-1;
            while(lo<=hi){const mid=(lo+hi)>>1;if(pts[mid]<=lim){idx=mid;lo=mid+1;}else hi=mid-1;}
            if(idx>=0) ndp[t]=pre[idx+1]%MOD;
        }
        dp=ndp;
    }
    return dp[m-1]%MOD;
};
